[CONSULT_SPECIALIST 결과 — 재활의학과]
[K-Doctor 전문과목 재활의학과 v0.1 적용]

`RED_FLAG` — 다만 질문 맥락(발병 8주, 만성기 재활)에서 **급성 응급 신호는 입력에 없음**. 확인 불가 항목이 많아 아래 소견은 **조건부**다.

═══════════════════════════════════════
[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-rehabilitation",

  "answer": "질문 4개 모두 **개별 환자 맞춤 처방이 아니라 일반 원칙**으로만 답할 수 있다. 연령·병변부위·MAS·보행수준·동반질환이 없어 (1)~(3)의 구체 단계 목표·프로토콜 수치는 제시하지 않는다. 대신 ① 설정 원칙(단계 목표는 MAS·보행수준별로 대면에서 확정), ② 경직 관리 시점의 일반 기준, ③ 보행훈련의 일반 진행 순서, ④ 만성기 배제 항목을 근거등급과 함께 제시한다. 구체 프로토콜 수치(세트·반복·시간·강도·보툴리눔 용량)는 쓸 수 없다(공통규칙 ④, 재활 규칙 1).",

  "red_flag": {
    "present": false,
    "items": [
      { "id": "W1", "evidence": "입력에 새로 발생한 마비·의식·언어 변화 없음(발병 8주 경과)", "basis": "history" },
      { "id": "W3", "evidence": "배뇨·배변 변화 언급 없음 — 확인되지 않음(확인 필요)", "basis": "history" },
      { "id": "W5", "evidence": "운동 시 흉통·숨참·실신 전 어지럼 언급 없음 — 확인되지 않음(재활 규칙 2에 따라 운동 소견 전 확인 필요)", "basis": "history" },
      { "id": "W7", "evidence": "편마비측 하지 부종·통증·열감 언급 없음 — 편마비 환자에서 DVT 위험은 상존하므로 대면에서 확인", "basis": "history" }
    ]
  },

  "hypotheses": [
    {
      "name": "만성기 뇌졸중(발병 8주) 편마비·경직 — 재활 단계 평가 필요",
      "icd10": "I69.3 (뇌경색 후유증) / I69.1 (뇌출혈 후유증) — 병변 유형 미상",
      "must_not_miss": true,
      "probability_band": "high",
      "supports": [
        { "text": "발병 후 8주, 편마비 + 경직 — 만성기 진입, 기능 회복·경직 관리 시기", "basis": "history" }
      ],
      "against": [
        { "text": "연령·병변부위·초기 중증도(NIHSS) 미상 — 예후 예측 불가", "basis": "history" }
      ]
    },
    {
      "name": "만성기 합병증(구축·DVT·우울·인지저하·연하장애·경직성 통증·복합부위통증증후군 CRPS)",
      "icd10": "M62.4(구축) / I80(정맥혈전) / F32(우울) 등",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "편마비 + 경직 + 발병 8주는 구축·DVT·경직성 통증·CRPS 위험 시기", "basis": "guideline" }
      ],
      "against": [
        { "text": "개별 위험 인자(부종, 통각과민, 피부변화, ADL 저하, 감정 변화) 미확인", "basis": "history" }
      ]
    }
  ],

  "missing_info": [
    "MAS 등급(주관절·수근·고관절·슬관절·족관절), 보행 수준(FAC 또는 독립/보조기), 연령, 병변부위(피질/피질하/기저핵/시상), 동반질환(심장·당뇨·인지), 현재 복용 약물"
  ],

  "suggested_tests": [
    { "name": "MAS(Modified Ashworth Scale) 및 Tardieu Scale 평가", "purpose": "경직 정도·속도 의존성 정량화 — 보툴리눔·경구약 적응 판단", "urgency": "routine", "basis": "guideline" },
    { "name": "보행능력 평가(FAC, 10m 보행속도, TUG, Berg Balance)", "purpose": "보행훈련 단계 결정", "urgency": "routine", "basis": "guideline" },
    { "name": "하지 도플러 초음파(편마비측 부종 시)", "purpose": "만성기 DVT 배제", "urgency": "24h", "basis": "guideline" },
    { "name": "일상생활동작(MBI/BI), 인지(MMSE/MoCA), 정서(PHQ-9) 선별", "purpose": "재활 목표 설정과 우울·인지 동반 확인", "urgency": "routine", "basis": "guideline" }
  ],

  "suggested_treatments": [
    {
      "kind": "referral",
      "description": "[일반 원칙 — 개별 처방 아님] (1) 재활 목표 설정: MAS·보행수준·ADL·인지·정서를 대면에서 평가한 뒤 단계 목표 설정. 통상 ICF(손상-활동-참여) 3층으로 목표를 나누고, 손상층(경직·근력)은 활동층(보행·ADL)과 참여층(사회복귀)에 종속시켜 설정한다. 구체 수치는 대면 평가 후 재활의학과 전문의·치료사가 확정.",
      "basis": "guideline"
    },
    {
      "kind": "referral",
      "description": "[경직 관리 일반 원칙] ① 경직이 통증·위생·자세·ADL·보행을 방해할 때 치료 적응. ② 물리치료(스트레칭·자세·냉온·전기자극)는 경직의 1차 접근. ③ 경구약(baclofen, tizanidine, dantrolene 등)은 전신 부작용(진정·간독성 등) 고려해 신중. ④ 보툴리눔 국소치료는 국소 경직이 기능·위생을 방해할 때 적응이며, **국소 보툴리눔은 3~6개월 간격 반복이 일반적**이고, 길항근 약화로 기능 악화 가능성이 있어 재활 목표와 함께 결정. 용량·제품·주입근육은 재활의학과·재활 전문의가 결정(공통규칙 ④).",
      "basis": "guideline"
    },
    {
      "kind": "referral",
      "description": "[보행훈련 일반 진행 순서 — 구체 프로토콜 아님] 체중지지·자세·균형(부분 체중지지 트레드밀 또는 지지대 이용) → 보조기/보조도구(지팡이·워커·AFO) 사용 단계 → 보행속도·지구력·계단·장애물 단계 → 지역사회 보행. 각 단계 전환은 대면 보행평가(FAC·10m·TUG·Berg)로 결정하며, 구체 시간·거리·세트 수치는 쓰지 않는다(재활 규칙 1).",
      "basis": "guideline"
    },
    {
      "kind": "self_care",
      "description": "[구축·만성 합병증 예방 — 일반 수준] 관절가동범위 유지, 자세 교정, 낙상 예방 환경(조명·미끄럼·문턱·보조기), 압박 예방(피부 확인), 편마비측 부종 확인. 세부 강도·시간은 대면에서 처방.",
      "basis": "guideline"
    },
    {
      "kind": "referral",
      "description": "[대면 평가 우선] 상기 모든 항목은 재활의학과 대면 평가 후 확정. 원격 소견은 기존 재활 계획을 대체하지 않는다(재활 규칙 4).",
      "basis": "guideline"
    }
  ],

  "handoff": {
    "better_specialty": "kdoctor-neurology(뇌졸중 병변·재발 평가), kdoctor-anesthesiology-pain(만성 경직성 통증·CRPS), kdoctor-psychiatry(우울 동반 시)",
    "reason": "뇌졸중 원인·재발 위험 평가는 신경과, 만성 통증·CRPS는 통증의학, 정서 동반은 정신건강의학과가 더 적합."
  },

  "confidence": { "clinical": 2, "information": 1 },

  "warnings": [
    "전문의 검토 전 초안. 실행 검증 전.",
    "MAS·보행수준·연령·병변부위 미상이므로 단계 목표·프로토콜 수치는 제시하지 않음.",
    "구체 운동 강도·세트·시간·보툴리눔 용량은 재활 규칙 1·공통규칙 ④에 따라 쓰지 않음.",
    "편마비측 부종·흉통·숨참·어지럼·배뇨배변 변화는 대면 확인 필요."
  ]
}
[/SPECIALIST_FINDING]

